/// <summary>
/// Scoped (per-circuit) state holding the latest low-stock alert count.
/// Components subscribe to <see cref="OnChange"/> to be notified when the
/// count is updated. Because timer callbacks fire outside the Blazor
/// synchronization context, subscribers must wrap StateHasChanged in
/// InvokeAsync.
/// </summary>
public class InventoryAlertState
{
    public int LowStockCount { get; private set; }

    public event Action? OnChange;

    public void UpdateCount(int count)
    {
        LowStockCount = count;
        OnChange?.Invoke();
    }
}

