@using sv_6159ce9ceaa545018e7ecf7a28276743.Services
@inject CascadingValueSource<WarehouseInfo> WarehouseSource
@rendermode InteractiveServer

<select class="form-select form-select-sm"
        style="width: auto; display: inline-block;"
        value="@_selectedId"
        @onchange="OnWarehouseChanged">
    @foreach (var wh in WarehouseInfo.All)
    {
        <option value="@wh.Id">@wh.Name</option>
    }
</select>

@code {
    private string _selectedId = WarehouseInfo.All[0].Id;

    private async Task OnWarehouseChanged(ChangeEventArgs e)
    {
        _selectedId = e.Value?.ToString() ?? WarehouseInfo.All[0].Id;
        var selected = WarehouseInfo.All.FirstOrDefault(w => w.Id == _selectedId)
                       ?? WarehouseInfo.All[0];

        // Pushes the new value to every [CascadingParameter] subscriber.
        await WarehouseSource.NotifyChangedAsync(
            new WarehouseInfo { Id = selected.Id, Name = selected.Name });
    }
}

@using sv_6159ce9ceaa545018e7ecf7a28276743.Services
@inject InventoryAlertState AlertState
@implements IDisposable
@rendermode InteractiveServer

@if (AlertState.LowStockCount > 0)
{
    <span class="badge bg-danger rounded-pill ms-2">@AlertState.LowStockCount</span>
}

@code {
    private Action? _handler;

    protected override void OnInitialized()
    {
        // Timer callbacks fire outside Blazor's sync context, so wrap in InvokeAsync.
        _handler = () => InvokeAsync(StateHasChanged);
        AlertState.OnChange += _handler;
    }

    public void Dispose()
    {
        AlertState.OnChange -= _handler;
    }
}

