@page "/dashboard"
@using sv_6159ce9ceaa545018e7ecf7a28276743.Services
@inject InventoryAlertService AlertService
@inject InventoryAlertState AlertState
@implements IDisposable
@rendermode InteractiveServer

<PageTitle>Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="card mt-3" style="max-width: 30rem;">
    <div class="card-body">
        <h5 class="card-title">@Warehouse?.Name</h5>
        <p class="card-text">
            Low-stock alerts:
            @if (AlertState.LowStockCount > 0)
            {
                <span class="badge bg-danger">@AlertState.LowStockCount items below minimum</span>
            }
            else
            {
                <span class="badge bg-success">All stock levels OK</span>
            }
        </p>
        <p class="text-muted mb-0">
            <small>Polling every 10 s &mdash; last check @_lastCheck?.ToString("T")</small>
        </p>
    </div>
</div>

@code {
    [CascadingParameter]
    private WarehouseInfo? Warehouse { get; set; }

    private PeriodicTimer? _timer;
    private CancellationTokenSource? _cts;
    private DateTime? _lastCheck;
    private Action? _handler;

    protected override void OnInitialized()
    {
        // Subscribe so this component re-renders when AlertState changes
        // (e.g. if another component updated the count).
        _handler = () => InvokeAsync(StateHasChanged);
        AlertState.OnChange += _handler;
    }

    protected override void OnParametersSet()
    {
        // Restart polling whenever the warehouse changes.
        StopPolling();
        StartPolling();
    }

    private void StartPolling()
    {
        _cts = new CancellationTokenSource();
        _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
        _ = PollLoopAsync(_cts.Token);
    }

    private async Task PollLoopAsync(CancellationToken ct)
    {
        // Fetch immediately, then every 10 seconds.
        await FetchAlertCountAsync();

        try
        {
            while (await _timer!.WaitForNextTickAsync(ct))
            {
                await FetchAlertCountAsync();
            }
        }
        catch (OperationCanceledException) { }
    }

    private async Task FetchAlertCountAsync()
    {
        var warehouseId = Warehouse?.Id ?? "WH-1";
        var count = await AlertService.GetLowStockCountAsync(warehouseId);

        // Update the shared state — this notifies ALL subscribers (sidebar badge, etc.).
        AlertState.UpdateCount(count);
        _lastCheck = DateTime.Now;
    }

    private void StopPolling()
    {
        _cts?.Cancel();
        _cts?.Dispose();
        _cts = null;
        _timer?.Dispose();
        _timer = null;
    }

    public void Dispose()
    {
        StopPolling();
        AlertState.OnChange -= _handler;
    }
}

